167	/**
168	 * Returns the valid target node type IDs for a given relation type and source
169	 * node type, checking both forward and reverse directions.
170	 */
171	export const getCompatibleTargetNodeTypeIds = ({
172	  discourseRelations,
173	  relationTypeId,
174	  sourceNodeTypeId,
175	}: {
176	  discourseRelations: DiscourseRelation[];
177	  relationTypeId: string;
178	  sourceNodeTypeId: string;
179	}): string[] => {
180	  const targets = new Set<string>();
181	  for (const relation of discourseRelations) {
182	    if (relation.relationshipTypeId !== relationTypeId) continue;
183	    if (relation.sourceId === sourceNodeTypeId)
184	      targets.add(relation.destinationId);
185	    if (relation.destinationId === sourceNodeTypeId)
186	      targets.add(relation.sourceId);
187	  }
188	  return [...targets];
189	};
