191	/**
192	 * Checks whether any valid relation type exists between two node types.
193	 */
194	export const hasValidRelationTypeForNodePair = ({
195	  settings,
196	  sourceNodeTypeId,
197	  targetNodeTypeId,
198	}: {
199	  settings: RelationTypeSettings;
200	  sourceNodeTypeId: string;
201	  targetNodeTypeId: string;
202	}): boolean => {
203	  return settings.discourseRelations.some(
204	    (r) =>
205	      settings.relationTypes.some((rt) => rt.id === r.relationshipTypeId) &&
206	      ((r.sourceId === sourceNodeTypeId &&
207	        r.destinationId === targetNodeTypeId) ||
208	        (r.sourceId === targetNodeTypeId &&
209	          r.destinationId === sourceNodeTypeId)),
210	  );
211	};
